def join_swarm(bootstrap_addr, file_id):
    peer_list = ask_bootstrap(bootstrap_addr, file_id)
    connections = []
    for peer_addr in peer_list:
        conn = try_connect(peer_addr)
        if conn:
            connections.append(conn)
    return connections

def download_file(connections, piece_hashes):
    have = set()
    need = set(range(len(piece_hashes)))
    while need:
        piece_index = pick_rarest_piece(need, connections)
        source = pick_peer_with_piece(connections, piece_index)
        data = request_piece(source, piece_index)
        if hash(data) == piece_hashes[piece_index]:
            save_piece(piece_index, data)
            have.add(piece_index)
            need.remove(piece_index)
            announce_have(connections, piece_index)
        else:
            drop_connection(source)  # bad or corrupted peer
    return assemble_file(have)

